                continue

            comp = []
            q = deque([(r, c)])
            seen.add((r, c))
            touches_edge = False

            while q:
                y, x = q.popleft()
                comp.append((y, x))
                if y == 0 or y == h - 1 or x == 0 or x == w - 1:
                    touches_edge = True
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= ny < h and 0 <= nx < w and
